class TwoSlotStrategy(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol

        self.symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        self.spy_sma = SimpleMovingAverage(100)
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self.previous_spy_close = None
        self.previous_spy_sma = None
        self.spy_cross_above = False
        self.spy_cross_below = False

        self.previous_aapl_close = None
        self.aapl_red_days = 0

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0

        self.pending_orders = {}
        self.pending_slots = {}
        self.submitting_order = None

        self.SetWarmUp(100, Resolution.Daily)

    def OnData(self, data):
        bars = data.Bars

        spy_bar = bars[self.spy] if bars.ContainsKey(self.spy) else None
        aapl_bar = bars[self.aapl] if bars.ContainsKey(self.aapl) else None

        if spy_bar is not None:
            previous_sma = (
                self.spy_sma.Current.Value
                if self.spy_sma.IsReady
                else None
            )
            previous_close = self.previous_spy_close

            self.spy_sma.Update(spy_bar.EndTime, spy_bar.Close)

            self.spy_cross_above = False
            self.spy_cross_below = False

            if (
                previous_close is not None
                and previous_sma is not None
                and self.spy_sma.IsReady
            ):
                current_sma = self.spy_sma.Current.Value
                self.spy_cross_above = (
                    previous_close <= previous_sma
                    and spy_bar.Close > current_sma
                )
                self.spy_cross_below = (
                    previous_close >= previous_sma
                    and spy_bar.Close < current_sma
                )

            self.previous_spy_close = spy_bar.Close
            self.previous_spy_sma = (
                self.spy_sma.Current.Value
                if self.spy_sma.IsReady
                else None
            )

        if aapl_bar is not None:
            self.aapl_rsi.Update(aapl_bar.EndTime, aapl_bar.Close)

            if self.previous_aapl_close is None:
                self.aapl_red_days = 0
            elif aapl_bar.Close < self.previous_aapl_close:
                self.aapl_red_days += 1
            else:
                self.aapl_red_days = 0

            self.previous_aapl_close = aapl_bar.Close

        if self.IsWarmingUp:
            return

        if not all(bars.ContainsKey(symbol) for symbol in self.symbols):
            return

        if not self.spy_sma.IsReady or not self.aapl_rsi.IsReady:
            return

        if self.strategy_a_lot > 0 and self.spy_cross_below:
            self._submit_order(
                "A",
                self.spy,
                -self.strategy_a_lot,
                "A_SELL"
            )

        if (
            self.strategy_b_lot > 0
            and self.aapl_rsi.Current.Value > 60
        ):
            self._submit_order(
                "B",
                self.aapl,
                -self.strategy_b_lot,
                "B_SELL"
            )

        if (
            self.strategy_a_lot == 0
            and "A" not in self.pending_slots
            and self.spy_cross_above
            and spy_bar.Close > 0
        ):
            quantity = int(
                0.40 * float(self.Portfolio.TotalPortfolioValue)
                / float(spy_bar.Close)
            )
            if quantity > 0:
                self._submit_order(
                    "A",
                    self.spy,
                    quantity,
                    "A_BUY"
                )

        if (
            self.strategy_b_lot == 0
            and "B" not in self.pending_slots
            and self.aapl_red_days >= 3
            and float(self.Portfolio.Cash) >= 20000
            and aapl_bar.Close > 0
        ):
            quantity = int(20000 / float(aapl_bar.Close))
            if quantity > 0:
                self._submit_order(
                    "B",
                    self.aapl,
                    quantity,
                    "B_BUY"
                )

    def _submit_order(self, slot, symbol, quantity, tag):
        if quantity == 0 or slot in self.pending_slots:
            return

        side = 1 if quantity > 0 else -1
        self.pending_slots[slot] = side
        self.submitting_order = (slot, side)

        ticket = self.MarketOrder(symbol, quantity, tag=tag)

        self.submitting_order = None

        if ticket is None:
            self.pending_slots.pop(slot, None)
            return

        if slot in self.pending_slots:
            self.pending_orders[ticket.OrderId] = (slot, side)

    def OnOrderEvent(self, order_event):
        record = self.pending_orders.get(order_event.OrderId)

        if record is None:
            order = self.Transactions.GetOrderById(order_event.OrderId)
            if order is not None:
                tag = order.Tag
                if tag == "A_BUY":
                    record = ("A", 1)
                elif tag == "A_SELL":
                    record = ("A", -1)
                elif tag == "B_BUY":
                    record = ("B", 1)
                elif tag == "B_SELL":
                    record = ("B", -1)

        if record is None and self.submitting_order is not None:
            record = self.submitting_order

        if record is None:
            return

        slot, side = record
        fill_quantity = int(order_event.FillQuantity)

        if fill_quantity != 0:
            filled_shares = abs(fill_quantity)

            if slot == "A":
                if side > 0:
                    self.strategy_a_lot += filled_shares
                else:
                    self.strategy_a_lot = max(
                        0,
                        self.strategy_a_lot - filled_shares
                    )
            else:
                if side > 0:
                    self.strategy_b_lot += filled_shares
                else:
                    self.strategy_b_lot = max(
                        0,
                        self.strategy_b_lot - filled_shares
                    )

        if order_event.Status in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        ):
            self.pending_orders.pop(order_event.OrderId, None)

            if self.pending_slots.get(slot) == side:
                self.pending_slots.pop(slot, None)
